from __future__ import annotations

from dataclasses import dataclass

from payment_models import PaymentIntent
from policy_reasons import (
    DENY_CANCELED,
    DENY_FAILED,
    DENY_UNKNOWN,
    GRANT,
    GRANT_CAPTURED,
    GRANT_SETTLED,
    HOLD,
    HOLD_AUTHORIZED_NOT_CAPTURED,
    HOLD_PROCESSING,
    HOLD_REQUIRES_ACTION,
    HOLD_UNCONFIRMED,
    disposition_for_reason,
)


@dataclass(frozen=True)
class GrantDecision:
    """Outcome of evaluating a PaymentIntent for entitlement.

    ``disposition`` is one of grant / hold / deny. ``should_grant`` is the
    single boolean fulfillment reads. ``reason`` is a stable code; ``terminal``
    means no further state change can move this intent to a grant.
    """

    intent_id: str
    disposition: str
    reason: str
    should_grant: bool
    terminal: bool

    def as_dict(self) -> dict[str, object]:
        return {
            "intent_id": self.intent_id,
            "disposition": self.disposition,
            "reason": self.reason,
            "should_grant": self.should_grant,
            "terminal": self.terminal,
        }


# Statuses the policy currently considers "money is good enough to unlock".
# Automatic-capture intents settle straight to succeeded. Intents that are
# mid-flow still report an intermediate status while the customer finishes
# authentication or the bank processes the charge.
_PAYABLE_STATUSES = {
    "succeeded",
    "requires_action",
    "processing",
    "requires_capture",
}


def _reason_for_status(intent: PaymentIntent) -> str:
    status = intent.status
    if status == "succeeded":
        return GRANT_SETTLED
    if status == "requires_capture":
        # Manual-capture authorization. Funds are held against the card.
        return GRANT_CAPTURED
    if status == "requires_action":
        return HOLD_REQUIRES_ACTION
    if status == "processing":
        return HOLD_PROCESSING
    if status == "canceled":
        return DENY_CANCELED
    if status in {"requires_payment_method", "requires_confirmation"}:
        return HOLD_UNCONFIRMED
    return DENY_UNKNOWN


def evaluate_intent(intent: PaymentIntent) -> GrantDecision:
    """Decide whether a PaymentIntent should unlock access.

    Fulfillment should only happen once Stripe has actually moved money. The
    policy maps the intent status to a disposition and a reason code.
    """

    status = intent.status
    reason = _reason_for_status(intent)
    grant = status in _PAYABLE_STATUSES
    disposition = GRANT if grant else disposition_for_reason(reason)
    terminal = status in {"succeeded", "canceled"}
    return GrantDecision(
        intent_id=intent.intent_id,
        disposition=disposition,
        reason=reason,
        should_grant=grant,
        terminal=terminal,
    )


def evaluate_failed(intent: PaymentIntent) -> GrantDecision:
    """Decision for a payment_intent.payment_failed event.

    A failure is terminal-bad: it must never grant access, and if access was
    already granted it should be revoked by the coordinator.
    """

    return GrantDecision(
        intent_id=intent.intent_id,
        disposition="deny",
        reason=DENY_FAILED,
        should_grant=False,
        terminal=False,
    )


def evaluate_canceled(intent: PaymentIntent) -> GrantDecision:
    return GrantDecision(
        intent_id=intent.intent_id,
        disposition="deny",
        reason=DENY_CANCELED,
        should_grant=False,
        terminal=True,
    )


def revokes_access(decision: GrantDecision) -> bool:
    """Whether this decision means an existing grant must be pulled.

    Only an outright failure or cancellation should revoke. A hold (the payment
    is still in flight) should not revoke an existing active grant, but it must
    not create one either.
    """

    return decision.disposition == "deny"


def grants_access(decision: GrantDecision) -> bool:
    return decision.should_grant and decision.disposition == GRANT


def explain(decision: GrantDecision) -> str:
    if decision.disposition == GRANT:
        return f"{decision.intent_id}: granting access ({decision.reason})"
    if decision.disposition == HOLD:
        return f"{decision.intent_id}: holding ({decision.reason})"
    return f"{decision.intent_id}: denying ({decision.reason})"


class EntitlementPolicy:
    """Thin object wrapper so callers can inject a configured policy."""

    def __init__(self, require_full_capture: bool = True) -> None:
        # When True, a manual-capture intent must be fully captured (succeeded)
        # before access is granted. This flag exists for ops to reason about
        # manual-capture flows separately from automatic ones.
        self.require_full_capture = require_full_capture

    def decide(self, intent: PaymentIntent) -> GrantDecision:
        return evaluate_intent(intent)

    def decide_failed(self, intent: PaymentIntent) -> GrantDecision:
        return evaluate_failed(intent)

    def decide_canceled(self, intent: PaymentIntent) -> GrantDecision:
        return evaluate_canceled(intent)

