from __future__ import annotations

from payment_models import EntitlementGrant


class GrantStore:
    """Keeps at most one grant per intent id.

    Access is considered active when a grant exists for the intent and its
    ``active`` flag is True. Revoking flips the flag rather than deleting the
    row so the history of the grant survives for audit.
    """

    def __init__(self, seed: dict[str, EntitlementGrant] | None = None) -> None:
        self._by_intent: dict[str, EntitlementGrant] = dict(seed or {})

    def get(self, intent_id: str) -> EntitlementGrant | None:
        return self._by_intent.get(intent_id)

    def has_active_grant(self, intent_id: str) -> bool:
        grant = self._by_intent.get(intent_id)
        return grant is not None and grant.active

    def has_any_grant(self, intent_id: str) -> bool:
        return intent_id in self._by_intent

    def save(self, grant: EntitlementGrant) -> EntitlementGrant:
        self._by_intent[grant.intent_id] = grant
        return grant

    def grant(
        self,
        intent_id: str,
        sku: str,
        customer_id: str | None,
        event_id: str,
    ) -> EntitlementGrant:
        existing = self._by_intent.get(intent_id)
        if existing is not None and existing.active:
            # Already granted; keep the original grant id and event provenance.
            return existing
        grant = EntitlementGrant(
            grant_id=f"grant-{intent_id}",
            intent_id=intent_id,
            customer_id=customer_id,
            sku=sku,
            active=True,
            granted_from_event=event_id,
        )
        self._by_intent[intent_id] = grant
        return grant

    def revoke(self, intent_id: str, event_id: str) -> EntitlementGrant | None:
        existing = self._by_intent.get(intent_id)
        if existing is None:
            return None
        revoked = existing.revoked(event_id)
        self._by_intent[intent_id] = revoked
        return revoked

    def active_count(self) -> int:
        return sum(1 for grant in self._by_intent.values() if grant.active)

    def all_grants(self) -> list[EntitlementGrant]:
        return list(self._by_intent.values())

    def as_dict(self) -> dict[str, EntitlementGrant]:
        return dict(self._by_intent)

    def snapshot(self) -> dict[str, object]:
        return {
            "intent_count": len(self._by_intent),
            "active_count": self.active_count(),
            "intent_ids": sorted(self._by_intent),
        }


def store_from_prior(prior: dict[str, EntitlementGrant] | None) -> GrantStore:
    return GrantStore(prior)


def copy_store_back(store: GrantStore, target: dict[str, EntitlementGrant] | None) -> None:
    if target is None:
        return
    target.clear()
    target.update(store.as_dict())

