from __future__ import annotations

from payment_models import PaymentIntent, WebhookEvent
from webhook_ledger import order_events


# Maps an event type to the intent status it implies, when the event payload
# does not already carry a more specific status. The intent snapshot on the
# event is authoritative; this is only a fallback for sparse payloads.
_EVENT_STATUS_HINT = {
    "payment_intent.created": "requires_confirmation",
    "payment_intent.requires_action": "requires_action",
    "payment_intent.processing": "processing",
    "payment_intent.amount_capturable_updated": "requires_capture",
    "payment_intent.succeeded": "succeeded",
    "payment_intent.payment_failed": "requires_payment_method",
    "payment_intent.canceled": "canceled",
}


def project_current_intent(events: list[WebhookEvent]) -> PaymentIntent | None:
    """Fold a stream of events into the latest known PaymentIntent state.

    Events are replayed in real ordering (by created, then sequence) so that a
    late-arriving stale event does not overwrite a newer state. The intent
    snapshot carried on the newest event wins.
    """

    if not events:
        return None
    ordered = order_events(events)
    return ordered[-1].intent


def status_timeline(events: list[WebhookEvent]) -> list[str]:
    ordered = order_events(events)
    return [event.intent.status for event in ordered]


def reached_succeeded(events: list[WebhookEvent]) -> bool:
    return any(event.intent.status == "succeeded" for event in events)


def ever_failed(events: list[WebhookEvent]) -> bool:
    return any(event.event_type == "payment_intent.payment_failed" for event in events)


def implied_status(event: WebhookEvent) -> str:
    """Best-effort status for an event, preferring the payload snapshot."""

    if event.intent.status:
        return event.intent.status
    return _EVENT_STATUS_HINT.get(event.event_type, "requires_payment_method")


def is_state_advancing(previous: WebhookEvent | None, candidate: WebhookEvent) -> bool:
    """Whether ``candidate`` represents a newer state than ``previous``."""

    if previous is None:
        return True
    return candidate.ordering_key > previous.ordering_key


def summarize_projection(events: list[WebhookEvent]) -> dict[str, object]:
    intent = project_current_intent(events)
    return {
        "event_count": len(events),
        "current_status": intent.status if intent is not None else None,
        "timeline": status_timeline(events),
        "reached_succeeded": reached_succeeded(events),
        "ever_failed": ever_failed(events),
    }

