from __future__ import annotations


# Reason codes returned alongside a grant decision so support can read why a
# customer did or did not get access. These are stable identifiers used by
# dashboards and tests, not free text.
GRANT_SETTLED = "payment_settled"
GRANT_CAPTURED = "payment_captured"

HOLD_REQUIRES_ACTION = "awaiting_customer_authentication"
HOLD_PROCESSING = "payment_processing"
HOLD_AUTHORIZED_NOT_CAPTURED = "authorized_not_captured"
HOLD_UNCONFIRMED = "payment_unconfirmed"

DENY_FAILED = "payment_failed"
DENY_CANCELED = "payment_canceled"
DENY_UNKNOWN = "unknown_state"


# A decision is one of these three dispositions.
GRANT = "grant"
HOLD = "hold"
DENY = "deny"

VALID_DISPOSITIONS = {GRANT, HOLD, DENY}


# Maps an intent status to whether it is terminal-good, terminal-bad, or pending.
TERMINAL_GOOD_STATUSES = {"succeeded"}
TERMINAL_BAD_STATUSES = {"canceled"}
PENDING_STATUSES = {
    "requires_payment_method",
    "requires_confirmation",
    "requires_action",
    "processing",
    "requires_capture",
}


def disposition_for_reason(reason: str) -> str:
    """Group a reason code into its disposition bucket."""

    if reason in {GRANT_SETTLED, GRANT_CAPTURED}:
        return GRANT
    if reason in {DENY_FAILED, DENY_CANCELED, DENY_UNKNOWN}:
        return DENY
    return HOLD


def is_grant(disposition: str) -> bool:
    return disposition == GRANT


def is_terminal(status: str) -> bool:
    return status in TERMINAL_GOOD_STATUSES or status in TERMINAL_BAD_STATUSES


def describe_disposition(disposition: str) -> str:
    if disposition == GRANT:
        return "Access granted: payment settled."
    if disposition == HOLD:
        return "Access held: payment not settled yet."
    if disposition == DENY:
        return "Access denied: payment will not settle."
    return "Unknown disposition."


def normalize_reason(reason: str | None) -> str:
    if reason is None:
        return DENY_UNKNOWN
    if not reason.strip():
        return DENY_UNKNOWN
    return reason

