from __future__ import annotations

from payment_models import WebhookEvent


class WebhookLedger:
    """Tracks which webhook events have already been applied.

    Stripe redelivers events on timeout, so the same ``event_id`` can arrive
    more than once. The ledger records seen event ids so the coordinator can
    skip duplicates. It also remembers the high-water ordering key applied per
    intent so a late, stale event can be recognized as out-of-order.
    """

    def __init__(self) -> None:
        self._seen_event_ids: set[str] = set()
        self._high_water: dict[str, tuple[int, int]] = {}
        self._applied_count = 0

    def already_applied(self, event: WebhookEvent) -> bool:
        return event.event_id in self._seen_event_ids

    def mark_applied(self, event: WebhookEvent) -> None:
        self._seen_event_ids.add(event.event_id)
        self._applied_count += 1
        current = self._high_water.get(event.intent_id)
        if current is None or event.ordering_key > current:
            self._high_water[event.intent_id] = event.ordering_key

    def high_water_for(self, intent_id: str) -> tuple[int, int] | None:
        return self._high_water.get(intent_id)

    def is_stale(self, event: WebhookEvent) -> bool:
        """True when an older event arrives after a newer one was applied."""

        current = self._high_water.get(event.intent_id)
        if current is None:
            return False
